// ─────────────────────────────────────────────────────────────────────────
//  01 · the {} rules★★☆
//  concepts: parameterised messages · escaped placeholders · the trailing Throwable
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    /** What a logging call ends up with: the message and the exception to print with its stack trace. */
    record Formatted(String message, Throwable throwable) {}

    static Formatted format(String pattern, Object... args) {
        Object[] values = args == null ? new Object[0] : args;
        Throwable throwable = null;
        int placeholders = countPlaceholders(pattern);
        if (values.length > placeholders && values[values.length - 1] instanceof Throwable t) {
            throwable = t;
            values = Arrays.copyOf(values, values.length - 1);
        }
        var out = new StringBuilder();
        int next = 0;
        int i = 0;
        while (i < pattern.length()) {
            int j = pattern.indexOf("{}", i);
            if (j < 0 || next >= values.length) break;
            boolean escaped = j > 0 && pattern.charAt(j - 1) == '\\';
            boolean doubleEscaped = escaped && j > 1 && pattern.charAt(j - 2) == '\\';
            if (escaped && !doubleEscaped) {
                out.append(pattern, i, j - 1).append("{}");
            } else {
                out.append(pattern, i, escaped ? j - 1 : j).append(render(values[next++]));
            }
            i = j + 2;
        }
        out.append(pattern.substring(i));
        return new Formatted(out.toString(), throwable);
    }

    static int countPlaceholders(String pattern) {
        int n = 0;
        for (int j = pattern.indexOf("{}"); j >= 0; j = pattern.indexOf("{}", j + 2)) {
            boolean escaped = j > 0 && pattern.charAt(j - 1) == '\\';
            boolean doubleEscaped = escaped && j > 1 && pattern.charAt(j - 2) == '\\';
            if (!escaped || doubleEscaped) n++;
        }
        return n;
    }

    static String render(Object v) {
        if (v instanceof Object[] a) return Arrays.deepToString(a);
        if (v instanceof int[] a) return Arrays.toString(a);
        if (v instanceof long[] a) return Arrays.toString(a);
        return String.valueOf(v);
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("placeholders are filled in order", () -> {
            eq(format("order {} paid by {}", 42, "ana").message(), "order 42 paid by ana");
        });
        test("missing arguments leave their {} as they are; extra ones are ignored", () -> {
            eq(List.of(format("{} of {}", 3).message(), format("done", "unused").message()), List.of("3 of {}", "done"));
        });
        test("a trailing exception is kept apart, not printed into the message", () -> {
            var boom = new IllegalStateException("db down");
            var f = format("order {} failed", 42, boom);
            eq(List.of(f.message(), f.throwable() == boom), List.of("order 42 failed", true));
        });
        test("an escaped \\{} is printed literally and uses no argument", () -> {
            eq(format("set \\{} is not {}", "1,2").message(), "set {} is not 1,2");
        });
        test("a double backslash before {} keeps one backslash and substitutes", () -> {
            eq(format("C:\\\\{}", "file.zip").message(), "C:\\file.zip");
        });
        test("null and arrays are rendered readably", () -> {
            eq(format("{} {} {}", null, new int[] { 1, 2 }, new Object[] { "a", new String[] { "b" } }).message(), "null [1, 2] [a, [b]]");
        });
        test("no placeholders and no arguments: the pattern itself (boundary)", () -> {
            var f = format("started");
            eq(List.of(f.message(), String.valueOf(f.throwable())), List.of("started", "null"));
