// ─────────────────────────────────────────────────────────────────────────
//  02 · a request id across threads★★★
//  concepts: MDC per thread · set at the edge, clear in finally · capture and restore around pool tasks
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;

class Exercise {

    /** Given: a per-thread diagnostic context, like SLF4J's MDC (one map per thread). */
    static final class Mdc {
        private static final ThreadLocal<Map<String, String>> CONTEXT = new ThreadLocal<>();
        static void put(String key, String value) { var m = CONTEXT.get(); if (m == null) CONTEXT.set(m = new HashMap<>()); m.put(key, value); }
        static String get(String key) { var m = CONTEXT.get(); return m == null ? null : m.get(key); }
        static void remove(String key) { var m = CONTEXT.get(); if (m != null) m.remove(key); }
        static void clear() { CONTEXT.remove(); }
        /** a copy of this thread's context, or null when it has none */
        static Map<String, String> getCopyOfContextMap() { var m = CONTEXT.get(); return m == null ? null : new HashMap<>(m); }
        static void setContextMap(Map<String, String> context) { CONTEXT.set(new HashMap<>(context)); }
    }

    record Request(String path, Map<String, String> headers) {}
    record Response(int status, Map<String, String> headers, String body) {}

    /** The edge filter: one request id per request, in the MDC while the request runs and in the response. */
    static Response handle(Request request, Function<Request, Response> chain, Supplier<String> newId) {
        throw new UnsupportedOperationException("TODO: accept a valid X-Request-Id or generate one, put it in the MDC, echo it, clear it in finally");
    }

    /** Run task with the CALLER's context (captured now), then give the worker thread its own context back. */
    static Runnable wrap(Runnable task) {
        throw new UnsupportedOperationException("TODO: capture the context at wrap time, install it around the task, restore afterwards");
    }

    // Given: test helpers.
    static Request req(String id) { return new Request("/orders", id == null ? Map.of() : Map.of("X-Request-Id", id)); }
    static final Function<Request, Response> ECHO_MDC = r -> new Response(200, Map.of(), "rid=" + Mdc.get("requestId"));
    static String runOn(ExecutorService pool, Runnable task) throws Exception {
        var seen = new String[1];
        pool.submit(() -> { task.run(); seen[0] = "ok"; }).get(5, TimeUnit.SECONDS);
        return seen[0];
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("a valid incoming id is used in the MDC and echoed in the response", () -> {
            var r = handle(req("req-12345678"), ECHO_MDC, () -> "generated-1");
            eq(List.of(r.body(), r.headers().get("X-Request-Id")), List.of("rid=req-12345678", "req-12345678"));
        });
        test("a missing or malformed id is replaced, so nobody can inject log lines", () -> {
            var none = handle(req(null), ECHO_MDC, () -> "gen-00000001");
            var forged = handle(req("abc\nlevel=ERROR user=admin"), ECHO_MDC, () -> "gen-00000002");
            var tooShort = handle(req("abc"), ECHO_MDC, () -> "gen-00000003");
            eq(List.of(none.body(), forged.body(), tooShort.headers().get("X-Request-Id")), List.of("rid=gen-00000001", "rid=gen-00000002", "gen-00000003"));
        });
        test("the id is gone from the MDC after the request, even when the chain throws", () -> {
            handle(req("req-12345678"), ECHO_MDC, () -> "x");
            String afterOk = Mdc.get("requestId");
            raises(IllegalStateException.class, () -> handle(req("req-87654321"), r -> { throw new IllegalStateException("boom"); }, () -> "x"), "boom");
            eq(Arrays.asList(afterOk, Mdc.get("requestId")), Arrays.asList(null, null));
        });
        test("a task handed to a pool sees the caller's request id", () -> {
            var pool = Executors.newSingleThreadExecutor();
            var seen = new String[1];
            Mdc.put("requestId", "req-caller01");
            Runnable task = wrap(() -> seen[0] = Mdc.get("requestId"));
            Mdc.clear();
            runOn(pool, task);
            pool.shutdown();
            eq(seen[0], "req-caller01");
        });
        test("the context is captured when wrapping, not when the task runs", () -> {
            var pool = Executors.newSingleThreadExecutor();
            var seen = new String[1];
            Mdc.put("requestId", "req-first001");
            Runnable task = wrap(() -> seen[0] = Mdc.get("requestId"));
            Mdc.put("requestId", "req-second01");
            runOn(pool, task);
            Mdc.clear();
            pool.shutdown();
            eq(seen[0], "req-first001");
        });
        test("the worker thread gets its own context back afterwards (boundary)", () -> {
            var pool = Executors.newSingleThreadExecutor();
            runOn(pool, () -> Mdc.put("worker", "w1"));
            Mdc.put("requestId", "req-caller02");
            Runnable task = wrap(() -> {});
            Mdc.clear();
            runOn(pool, task);
            var after = new String[2];
            pool.submit(() -> { after[0] = Mdc.get("worker"); after[1] = Mdc.get("requestId"); }).get(5, TimeUnit.SECONDS);
            pool.shutdown();
            eq(Arrays.asList(after[0], after[1]), Arrays.asList("w1", null));
        });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

