// ─────────────────────────────────────────────────────────────────────────
//  02 · a request id across threads★★★
//  concepts: MDC per thread · set at the edge, clear in finally · capture and restore around pool tasks
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;

class Exercise {

    /** Given: a per-thread diagnostic context, like SLF4J's MDC (one map per thread). */
    static final class Mdc {
        private static final ThreadLocal<Map<String, String>> CONTEXT = new ThreadLocal<>();
        static void put(String key, String value) { var m = CONTEXT.get(); if (m == null) CONTEXT.set(m = new HashMap<>()); m.put(key, value); }
        static String get(String key) { var m = CONTEXT.get(); return m == null ? null : m.get(key); }
        static void remove(String key) { var m = CONTEXT.get(); if (m != null) m.remove(key); }
        static void clear() { CONTEXT.remove(); }
        /** a copy of this thread's context, or null when it has none */
        static Map<String, String> getCopyOfContextMap() { var m = CONTEXT.get(); return m == null ? null : new HashMap<>(m); }
        static void setContextMap(Map<String, String> context) { CONTEXT.set(new HashMap<>(context)); }
    }

    record Request(String path, Map<String, String> headers) {}
    record Response(int status, Map<String, String> headers, String body) {}

    static final java.util.regex.Pattern ID = java.util.regex.Pattern.compile("[A-Za-z0-9-]{8,64}");

    /** The edge filter: one request id per request, in the MDC while the request runs and in the response. */
    static Response handle(Request request, Function<Request, Response> chain, Supplier<String> newId) {
        String given = request.headers().get("X-Request-Id");
        String id = given != null && ID.matcher(given).matches() ? given : newId.get();
        Mdc.put("requestId", id);
        try {
            Response r = chain.apply(request);
            var headers = new TreeMap<>(r.headers());
            headers.put("X-Request-Id", id);
            return new Response(r.status(), headers, r.body());
        } finally {
            Mdc.remove("requestId");
        }
    }

    /** Run task with the CALLER's context (captured now), then give the worker thread its own context back. */
    static Runnable wrap(Runnable task) {
        Map<String, String> captured = Mdc.getCopyOfContextMap();
        return () -> {
            Map<String, String> previous = Mdc.getCopyOfContextMap();
            if (captured == null) Mdc.clear(); else Mdc.setContextMap(captured);
            try {
                task.run();
            } finally {
                if (previous == null) Mdc.clear(); else Mdc.setContextMap(previous);
            }
        };
    }

    // Given: test helpers.
    static Request req(String id) { return new Request("/orders", id == null ? Map.of() : Map.of("X-Request-Id", id)); }
    static final Function<Request, Response> ECHO_MDC = r -> new Response(200, Map.of(), "rid=" + Mdc.get("requestId"));
    static String runOn(ExecutorService pool, Runnable task) throws Exception {
        var seen = new String[1];
        pool.submit(() -> { task.run(); seen[0] = "ok"; }).get(5, TimeUnit.SECONDS);
        return seen[0];
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("a valid incoming id is used in the MDC and echoed in the response", () -> {
            var r = handle(req("req-12345678"), ECHO_MDC, () -> "generated-1");
