            var tooShort = handle(req("abc"), ECHO_MDC, () -> "gen-00000003");
            eq(List.of(none.body(), forged.body(), tooShort.headers().get("X-Request-Id")), List.of("rid=gen-00000001", "rid=gen-00000002", "gen-00000003"));
        });
        test("the id is gone from the MDC after the request, even when the chain throws", () -> {
            handle(req("req-12345678"), ECHO_MDC, () -> "x");
            String afterOk = Mdc.get("requestId");
            raises(IllegalStateException.class, () -> handle(req("req-87654321"), r -> { throw new IllegalStateException("boom"); }, () -> "x"), "boom");
            eq(Arrays.asList(afterOk, Mdc.get("requestId")), Arrays.asList(null, null));
        });
        test("a task handed to a pool sees the caller's request id", () -> {
            var pool = Executors.newSingleThreadExecutor();
            var seen = new String[1];
            Mdc.put("requestId", "req-caller01");
            Runnable task = wrap(() -> seen[0] = Mdc.get("requestId"));
            Mdc.clear();
            runOn(pool, task);
            pool.shutdown();
            eq(seen[0], "req-caller01");
        });
        test("the context is captured when wrapping, not when the task runs", () -> {
            var pool = Executors.newSingleThreadExecutor();
            var seen = new String[1];
            Mdc.put("requestId", "req-first001");
            Runnable task = wrap(() -> seen[0] = Mdc.get("requestId"));
            Mdc.put("requestId", "req-second01");
            runOn(pool, task);
            Mdc.clear();
            pool.shutdown();
            eq(seen[0], "req-first001");
        });
        test("the worker thread gets its own context back afterwards (boundary)", () -> {
            var pool = Executors.newSingleThreadExecutor();
            runOn(pool, () -> Mdc.put("worker", "w1"));
            Mdc.put("requestId", "req-caller02");
            Runnable task = wrap(() -> {});
            Mdc.clear();
            runOn(pool, task);
            var after = new String[2];
            pool.submit(() -> { after[0] = Mdc.get("worker"); after[1] = Mdc.get("requestId"); }).get(5, TimeUnit.SECONDS);
            pool.shutdown();
